-- 001_initial.sql
-- Club equipment loans: members borrow equipment; each borrowing is a loan.
-- Written from docs/data-model.md. Do not edit this file once it has been
-- applied to a database: add 002_..., 003_... instead.

CREATE TABLE member (
    id          INTEGER PRIMARY KEY,                 -- SQLite numbers these for us
    full_name   TEXT    NOT NULL,                    -- every member has a name
    email       TEXT    NOT NULL UNIQUE,             -- one membership per email address
    joined_on   TEXT    NOT NULL DEFAULT (date('now'))  -- stored as YYYY-MM-DD
);

CREATE TABLE equipment (
    id          INTEGER PRIMARY KEY,
    tag         TEXT    NOT NULL UNIQUE,             -- the label stuck on the item, e.g. TENT-01
    name        TEXT    NOT NULL,                    -- what it is, e.g. "4-person tent"
    condition   TEXT    NOT NULL DEFAULT 'good'
                CHECK (condition IN ('good', 'worn', 'broken'))
);

CREATE TABLE loan (
    id           INTEGER PRIMARY KEY,
    member_id    INTEGER NOT NULL
                 REFERENCES member(id) ON DELETE RESTRICT,     -- cannot delete a member who has loans
    equipment_id INTEGER NOT NULL
                 REFERENCES equipment(id) ON DELETE RESTRICT,  -- cannot delete equipment that has loans
    borrowed_on  TEXT    NOT NULL DEFAULT (date('now')),
    returned_on  TEXT,                                         -- empty (NULL) means still out
    CHECK (returned_on IS NULL OR returned_on >= borrowed_on)  -- cannot come back before it went out
);

-- The same item cannot be out on two open loans at once.
CREATE UNIQUE INDEX one_open_loan_per_item
    ON loan (equipment_id) WHERE returned_on IS NULL;
